    [arrive[1]!, '8'], [arrive[1]! + 0.15, '18', EASE_OUT], [arrive[2]!, '18'], [arrive[2]! + 0.15, '26', EASE_OUT],
    [arrive[3]!, '26'], [arrive[3]! + 0.15, '36', EASE_OUT], [arrive[4]!, '36'], [arrive[4]! + 0.15, '44', EASE_OUT],
    [6.0, '44'], [6.05, '0'], [D, '0'],
