  ]))
  const win = g(
    r(14, 3, 2, 2, C.orange) +
    px(64, 0, 48, 32, C.edge) + px(66, 2, 44, 6, C.ink2) +
    px(68, 4, 2, 2, C.red) + px(72, 4, 2, 2, C.yellow) + px(76, 4, 2, 2, C.green) + url +
