  const actor = at(X, TOP, sprite, mvT(D, [[0, '0 0'], [5.42, '0 0'], [5.56, '0 -8', EASE_OUT], [5.72, '0 0', EASE_IN], [D, '0 0']]))

  const check = popGlyph('✓', 166, 9, C.green, 2, D, 5.2, 6.3)
