// пиксельная иконка Wi-Fi (клетка 2 px), левый верх (x, y)
function wifi(x: number, y: number, fill: string): string {
  const rows = ['  #####  ', ' #     # ', '#  ###  #', '  #   #  ', '         ', '    #    ']
  let s = ''
  rows.forEach((row, yy) => { for (let xx = 0; xx < row.length; xx++) if (row[xx] === '#') s += px(x + xx * 2, y + yy * 2, 2, 2, fill) })
  return s
}

