  const flash = g(px(192, 30, 56, 24, C.green), fadeK([[0, [0]], [IN, [0], LIN], [IN + 0.08, [0.45], LIN], [IN + 0.5, [0], LIN], [T, [0], LIN]], T), ' opacity="0"')
